<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\WaiterCallService;

Auth::requirePermission('tables.manage');$tenantId=em_require_tenant();$unitId=Auth::unitId();
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='waiter-call-resolve'){
        try{(new WaiterCallService())->resolve($tenantId,(int)($_POST['id']??0));em_flash('ok','Chamada resolvida.');}catch(Throwable $e){em_flash('error',$e->getMessage());}em_go('restaurant');
    }
    if($action==='table-save'){
        $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$seats=max(1,(int)($_POST['seats']??4));if($name==='')exit('Nome da mesa inválido.');
        if($id){$sql='UPDATE restaurant_tables SET name=?,seats=?,status=? WHERE id=? AND tenant_id=?'.($unitId?' AND unit_id=?':'');$args=[$name,$seats,(string)($_POST['status']??'available'),$id,$tenantId];if($unitId)$args[]=$unitId;$s=$pdo->prepare($sql);$s->execute($args);}
        else{$s=$pdo->prepare('INSERT INTO restaurant_tables (tenant_id,unit_id,name,seats,status,qr_token) VALUES (?,?,?,?,"available",?)');$s->execute([$tenantId,$unitId,$name,$seats,bin2hex(random_bytes(20))]);$id=(int)$pdo->lastInsertId();}
        Auth::audit('table.saved','table',(string)$id,['unit_id'=>$unitId]);em_flash('ok','Mesa salva.');em_go('restaurant');
    }
    if($action==='tab-open'){
        $tableId=(int)($_POST['table_id']??0);$label=trim((string)($_POST['label']??''));$sql='SELECT id,status FROM restaurant_tables WHERE id=? AND tenant_id=?'.($unitId?' AND unit_id=?':'').' FOR UPDATE';$t=$pdo->prepare($sql);$pdo->beginTransaction();try{$args=[$tableId,$tenantId];if($unitId)$args[]=$unitId;$t->execute($args);$table=$t->fetch();if(!$table||$table['status']==='inactive')throw new RuntimeException('Mesa indisponível.');$open=$pdo->prepare('SELECT id FROM tabs WHERE tenant_id=? AND table_id=? AND status="open"');$open->execute([$tenantId,$tableId]);if($open->fetchColumn())throw new RuntimeException('A mesa já possui comanda aberta.');$s=$pdo->prepare('INSERT INTO tabs (tenant_id,table_id,opened_by,label,status) VALUES (?,?,?, ?,"open")');$s->execute([$tenantId,$tableId,Auth::id(),$label?:null]);$id=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE restaurant_tables SET status="occupied" WHERE id=?')->execute([$tableId]);$pdo->commit();Auth::audit('tab.opened','tab',(string)$id);em_flash('ok','Comanda aberta.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();em_flash('error',$e->getMessage());}em_go('restaurant');
    }
    if($action==='tab-close'){
        $id=(int)($_POST['id']??0);$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT tb.* FROM tabs tb JOIN restaurant_tables rt ON rt.id=tb.table_id WHERE tb.id=? AND tb.tenant_id=? AND tb.status="open"'.($unitId?' AND rt.unit_id=?':'').' FOR UPDATE');$args=[$id,$tenantId];if($unitId)$args[]=$unitId;$s->execute($args);$tab=$s->fetch();if(!$tab)throw new RuntimeException('Comanda não encontrada.');$u=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE tenant_id=? AND tab_id=? AND status<>"cancelled" AND payment_status<>"paid"');$u->execute([$tenantId,$id]);if((int)$u->fetchColumn()>0)throw new RuntimeException('Existem pedidos não pagos nesta comanda.');$pdo->prepare('UPDATE tabs SET status="closed",closed_by=?,closed_at=NOW() WHERE id=?')->execute([Auth::id(),$id]);if($tab['table_id'])$pdo->prepare('UPDATE restaurant_tables SET status="available" WHERE id=?')->execute([$tab['table_id']]);$pdo->commit();Auth::audit('tab.closed','tab',(string)$id);em_flash('ok','Comanda encerrada.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();em_flash('error',$e->getMessage());}em_go('restaurant');
    }
}

$callSql='SELECT wc.*,rt.name table_name,TIMESTAMPDIFF(MINUTE,wc.created_at,UTC_TIMESTAMP()) waiting_minutes FROM waiter_calls wc JOIN restaurant_tables rt ON rt.id=wc.table_id WHERE wc.tenant_id=? AND wc.status="open"'.($unitId?' AND rt.unit_id=?':'').' ORDER BY wc.created_at ASC';$callArgs=[$tenantId];if($unitId)$callArgs[]=$unitId;$callsStmt=$pdo->prepare($callSql);$callsStmt->execute($callArgs);$openCalls=$callsStmt->fetchAll();

$sql='SELECT rt.*,tb.id open_tab_id,tb.label,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") tab_total,(SELECT COALESCE(SUM(CASE WHEN o.payment_status<>"paid" THEN o.total_cents ELSE 0 END),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") unpaid_total FROM restaurant_tables rt LEFT JOIN tabs tb ON tb.table_id=rt.id AND tb.status="open" WHERE rt.tenant_id=?'.($unitId?' AND rt.unit_id=?':'').' ORDER BY rt.name';$args=[$tenantId];if($unitId)$args[]=$unitId;$s=$pdo->prepare($sql);$s->execute($args);$tables=$s->fetchAll();
em_header('Mesas e comandas','restaurant');
?><?php if($openCalls):?><section class="card" style="margin-bottom:18px;border-color:#f2b84b"><div class="section-head"><div><h2>Chamadas aguardando</h2><div class="muted">Atenda primeiro as solicitações mais antigas.</div></div><span class="badge"><?= count($openCalls) ?> aberta<?= count($openCalls)===1?'':'s' ?></span></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))"><?php foreach($openCalls as$call):$label=match($call['type']){'bill'=>'Pediu a conta','help'=>'Pediu ajuda',default=>'Chamou o garçom'};?><article style="padding:16px;border:1px solid var(--line);border-radius:16px"><strong><?= Security::e($call['table_name']) ?></strong><div style="margin:6px 0"><?= Security::e($label) ?></div><div class="muted">Aguardando há <?= max(0,(int)$call['waiting_minutes']) ?> min</div><form method="post" style="margin-top:10px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="waiter-call-resolve"><input type="hidden" name="id" value="<?= (int)$call['id'] ?>"><button class="primary">Marcar atendida</button></form></article><?php endforeach;?></div></section><?php endif;?><div class="grid" style="grid-template-columns:minmax(280px,1fr) minmax(0,2fr)"><section class="card"><h2>Nova mesa</h2><?php if($unitId):?><p class="muted">A mesa será criada na unidade selecionada.</p><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="table-save"><label>Nome<input name="name" placeholder="Mesa 01" required></label><label>Lugares<input type="number" name="seats" min="1" value="4"></label><button class="primary span-2">Criar mesa</button></form></section><section class="card"><div class="section-head"><h2>Salão</h2><span class="muted"><?= count($tables) ?> mesas</span></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))"><?php foreach($tables as $t):?><article class="card"><div class="section-head"><h3><?= Security::e($t['name']) ?></h3><span class="badge"><?= Security::e($t['status']) ?></span></div><p class="muted"><?= (int)$t['seats'] ?> lugares</p><?php if($t['open_tab_id']):?><p><strong>Comanda #<?= (int)$t['open_tab_id'] ?></strong> <?= Security::e($t['label']??'') ?><br>Total: <?= em_money($t['tab_total']) ?><br><span class="muted">Em aberto: <?= em_money($t['unpaid_total']) ?></span></p><form method="post" onsubmit="return confirm('Encerrar esta comanda?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tab-close"><input type="hidden" name="id" value="<?= (int)$t['open_tab_id'] ?>"><button class="secondary">Encerrar comanda</button></form><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tab-open"><input type="hidden" name="table_id" value="<?= (int)$t['id'] ?>"><label>Identificação<input name="label" placeholder="Ex.: João / aniversário"></label><button class="primary" style="margin-top:8px">Abrir comanda</button></form><?php endif;?><p style="margin-top:12px"><a href="<?= Security::e(em_url('/mesa.php?t='.urlencode((string)$t['qr_token']))) ?>" target="_blank">Link/QR da mesa</a></p></article><?php endforeach;?></div></section></div><?php em_footer();
